using System; using System.Data; using System.Data.SqlClient; using System.Configuration; using System.Web; using System.Security.Cryptography; using System.Collections.Generic; using System.Web.UI;
public class Datos {
public static SqlConnection Conexion(){return new SqlConnection(ConfigurationManager.ConnectionStrings["Barberia"].ConnectionString);}
public static SqlParameter P(string n,object v){return new SqlParameter(n,v);}
public static DataTable Tabla(string sql,params SqlParameter[] args){using(var c=Conexion())using(var cmd=new SqlCommand(sql,c)){cmd.Parameters.AddRange(args);using(var a=new SqlDataAdapter(cmd)){var dt=new DataTable();a.Fill(dt);return dt;}}}
public static void Ejecutar(string sql,params SqlParameter[] args){GuardarOperacion(sql,args);}
public static void GuardarOperacion(string sql,params SqlParameter[] args){using(var c=Conexion()){c.Open();using(var tx=c.BeginTransaction(IsolationLevel.Serializable)){using(var cmd=new SqlCommand(sql,c,tx)){cmd.Parameters.AddRange(args);cmd.ExecuteNonQuery();}tx.Commit();}}}
public static string Hash(string clave,string anterior=null){byte[] sal=new byte[16];if(anterior==null){using(var rng=RandomNumberGenerator.Create())rng.GetBytes(sal);}else sal=Convert.FromBase64String(anterior.Split(':')[0]);using(var k=new Rfc2898DeriveBytes(clave,sal,100000))return Convert.ToBase64String(sal)+":"+Convert.ToBase64String(k.GetBytes(32));}
public static string RolActual(){var c=HttpContext.Current;if(!c.User.Identity.IsAuthenticated)return "";var d=Tabla("SELECT Rol FROM Usuarios WHERE Usuario=@u AND Activo=1",P("@u",c.User.Identity.Name));return d.Rows.Count==0?"":Convert.ToString(d.Rows[0][0]);}
public static bool EsDueno(){return RolActual()=="Administrador";}
public static int PerfilId(string rol){var t=rol=="Cliente"?"UsuarioCliente":"UsuarioEmpleado";var campo=rol=="Cliente"?"ClienteId":"EmpleadoId";var d=Tabla("SELECT p."+campo+" FROM "+t+" p JOIN Usuarios u ON u.Id=p.UsuarioId WHERE u.Usuario=@u AND u.Activo=1",P("@u",HttpContext.Current.User.Identity.Name));return d.Rows.Count==0?0:Convert.ToInt32(d.Rows[0][0]);}
public static readonly Dictionary<string,string> Campos=new Dictionary<string,string>{{"Clientes","Nombre:s,Apellido:s,Telefono:s,Correo:s,Activo:b"},{"Empleados","Nombre:s,Apellido:s,Telefono:s,Correo:s,Especialidad:s,Activo:b"},{"Servicios","Nombre:s,Descripcion:s,DuracionMin:i,Precio:m,Activo:b"},{"Usuarios","Nombre:s,Usuario:s,Clave:s,Rol:s,Activo:b"},{"Productos","Nombre:s,Precio:m,StockMinimo:i,Activo:b"},{"Horarios","Empleado:rEmpleados,Dia:s,Entrada:t,Salida:t"},{"Recordatorios","Cita:rCitas,Tipo:s,Mensaje:s,FechaEnvio:h,Enviado:b"},{"Movimientos","Producto:rProductos,Tipo:s,Cantidad:i,Fecha:d"},{"Citas","Cliente:rClientes,Empleado:rEmpleados,Fecha:d,Hora:t,Estado:s,Observaciones:s"},{"DetalleCita","Cita:rCitas,Servicio:rServicios,Cantidad:i,PrecioUnitario:m"},{"Facturas","Cita:rCitas,Fecha:d"},{"DetalleFactura","Factura:rFacturas,Servicio:rServicios,Cantidad:i,PrecioUnitario:m"},{"MetodosPago","Nombre:s"},{"Pagos","Factura:rFacturas,Metodo:rMetodosPago,Monto:m,Fecha:d"}};
public static void Inicializar(){lock(typeof(Datos)){var b=new SqlConnectionStringBuilder(Conexion().ConnectionString);b.InitialCatalog="master";using(var c=new SqlConnection(b.ConnectionString)){c.Open();using(var cmd=new SqlCommand("SELECT DB_ID('db_barberia')",c)){if(Convert.IsDBNull(cmd.ExecuteScalar())){cmd.CommandText="CREATE DATABASE db_barberia";cmd.ExecuteNonQuery();}}}using(var c=Conexion()){c.Open();using(var tx=c.BeginTransaction()){using(var cmd=new SqlCommand("IF OBJECT_ID('Clientes') IS NULL BEGIN " + System.IO.File.ReadAllText(HttpContext.Current.Server.MapPath("~/App_Data/schema.sql")) + " END",c,tx)){cmd.ExecuteNonQuery();}using(var cmd=new SqlCommand("IF OBJECT_ID('UsuarioCliente') IS NULL CREATE TABLE UsuarioCliente(UsuarioId INT PRIMARY KEY REFERENCES Usuarios(Id) ON DELETE CASCADE, ClienteId INT NOT NULL UNIQUE REFERENCES Clientes(Id)); IF OBJECT_ID('UsuarioEmpleado') IS NULL CREATE TABLE UsuarioEmpleado(UsuarioId INT PRIMARY KEY REFERENCES Usuarios(Id) ON DELETE CASCADE, EmpleadoId INT NOT NULL UNIQUE REFERENCES Empleados(Id));",c,tx)){cmd.ExecuteNonQuery();}using(var cmd=new SqlCommand("IF NOT EXISTS(SELECT 1 FROM Usuarios WHERE Usuario=N'barberia') INSERT INTO Usuarios(Nombre,Usuario,Clave,Rol,Activo) VALUES('Administrador',N'barberia',@clave,'Administrador',1)",c,tx)){cmd.Parameters.AddWithValue("@clave",Hash("barberia123"));cmd.ExecuteNonQuery();}using(var cmd=new SqlCommand("IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Corte degradado') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Corte degradado',N'Degradado de cabello',40,8,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Corte infantil') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Corte infantil',N'Corte para niños',25,5,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Afeitado clásico') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Afeitado clásico',N'Afeitado con toalla caliente',20,4,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Perfilado de barba') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Perfilado de barba',N'Definición de barba',15,3,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Corte y barba') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Corte y barba',N'Servicio combinado',50,10,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Lavado de cabello') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Lavado de cabello',N'Lavado y secado',15,3,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Diseño de cejas') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Diseño de cejas',N'Perfilado de cejas',10,2,1); IF NOT EXISTS(SELECT 1 FROM Servicios WHERE Nombre=N'Tinte de cabello') INSERT INTO Servicios(Nombre,Descripcion,DuracionMin,Precio,Activo) VALUES(N'Tinte de cabello',N'Coloración',60,15,1);",c,tx)){cmd.ExecuteNonQuery();}tx.Commit();}}}}
}
public class PaginaBase:Page {
protected SqlConnection Conexion(){return Datos.Conexion();}
protected SqlParameter P(string n,object v){return Datos.P(n,v);}
protected DataTable Tabla(string sql,params SqlParameter[] args){return Datos.Tabla(sql,args);}
protected void Ejecutar(string sql,params SqlParameter[] args){Datos.Ejecutar(sql,args);}
protected void GuardarOperacion(string sql,params SqlParameter[] args){Datos.GuardarOperacion(sql,args);}
protected string Hash(string clave,string anterior=null){return Datos.Hash(clave,anterior);}
protected string RolActual(){return Datos.RolActual();}
protected bool EsDueno(){return Datos.EsDueno();}
protected int PerfilId(string rol){return Datos.PerfilId(rol);}
protected void Inicializar(){Datos.Inicializar();}
protected Dictionary<string,string> Campos {get{return Datos.Campos;}}}
public class Servicio {public int Id{get;set;} public string Nombre{get;set;} public string Descripcion{get;set;} public int DuracionMin{get;set;} public decimal Precio{get;set;} public bool Activo{get;set;}}